import os
import sqlite3
import stripe
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('orders')
stripe.api_key = os.environ['STRIPE_API_KEY']

@mcp.tool()
def refund_order_payment(payment_intent_id: str, amount_cents: int=None, reason: str='requested_by_customer') -> dict:
    args = {'payment_intent': payment_intent_id, 'reason': reason}
    if amount_cents is not None:
        if amount_cents <= 0:
            return {'ok': False, 'error': 'amount_cents must be positive'}
        args['amount'] = amount_cents
    try:
        r = stripe.Refund.create(**args)
    except stripe.error.StripeError as e:
        return {'ok': False, 'error': str(e)}
    if amount_cents is None:
        # Fully refunded orders should no longer be fulfilled
        conn = sqlite3.connect(os.environ.get('ORDERS_DB', 'orders.db'))
        with conn:
            conn.execute('DELETE FROM pending_fulfillments WHERE payment_intent_id = ?', (payment_intent_id,))
        conn.close()
    return {'ok': True, 'refund_id': r.id, 'status': r.status, 'amount': r.amount, 'currency': r.currency, 'payment_intent': payment_intent_id}
